"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[33886],{33886:function(e){e.exports=JSON.parse('{"generated":"2026-11-22 00:10 KST","source_file":"@reports/2026-11-22-raw.json","articles_total":26,"articles_summarized":26,"articles_skipped":0,"date_range":{"from":"2026-11-21","to":"2026-11-21"},"pages":[{"title":"Anthropic files S-1 with the SEC for proposed initial public offering","source":"https://www.anthropic.com/news/s1-sec","published_date":"Date not detected","type":"Business","what_its_about":"AI 기업 Anthropic이 미국 증권거래위원회(SEC)에 클래스 A 보통주 상장을 위한 S-1 증권신고서를 공식 제출했습니다.","key_points":["Anthropic, PBC가 미국 증권거래위원회(SEC)에 기업공개(IPO)를 위한 Form S-1 등록명세서를 제출함","나스닥 글로벌 셀렉트 마켓(Nasdaq Global Select Market)에 종목 코드 \'ANT\'로 클래스 A 보통주를 상장할 계획임","공모 주식 수와 희망 공모가 범위는 아직 결정되지 않았으며, 골드만삭스와 모건스탠리가 주관사로 참여함"],"notable_data_or_quotes":["Form S-1","Nasdaq Global Select Market","ANT","Goldman Sachs & Co. LLC","Morgan Stanley & Co. LLC"],"intended_audience":"AI 산업 투자자, 금융 및 증시 관계자, 테크 산업 분석가","content_notes":null},{"title":"Anthropic announces closing of initial public offering, including full exercise of underwriters’ option to purchase additional shares, and closing of concurrent private placement","source":"https://www.anthropic.com/news/ipo-close","published_date":"Date not detected","type":"Business","what_its_about":"Anthropic이 나스닥 상장을 위한 기업공개(IPO) 및 주요 빅테크 기업 대상의 사모 발행을 성공적으로 마무리했다.","key_points":["초과배정옵션을 포함해 총 1,127,000,000주의 Class A 보통주를 주당 $83.00에 매각하여 공모를 최종 마감했다.","IPO를 통해 약 $93.5 billion의 총 수익을 올렸으며, 이 중 Anthropic은 약 $91.6 billion을 조달했다.","NVIDIA, Google, Microsoft, AMD, Broadcom, TSMC 등 주요 빅테크 기업을 대상으로 약 $26.0 billion 규모의 Class N 보통주 사모 발행을 동시에 완료했다.","IPO와 사모 발행을 합산한 총 공모 조달 금액은 약 $119.5 billion에 달하며, 나스닥에서 \'ANT\' 티커로 거래를 시작했다."],"notable_data_or_quotes":["공모가: 주당 $83.00","IPO 총 발행 주식 수: 1,127,000,000주 (Anthropic 매각 1,103,351,354주, 기존 주주 매각 23,648,646주, 인수단 추가 매입 옵션 147,000,000주 전액 행사 포함)","사모 발행 규모: 313,253,007주 (약 $26.0 billion)","IPO 및 사모 발행 총 조달 금액: 약 $119.5 billion","나스닥 거래 개시일 및 티커: 2026년 11월 19일, “ANT”"],"intended_audience":"AI 산업 투자자, 금융 및 기술 시장 분석가, 기업 경영진","content_notes":null},{"title":"Anthropic prices initial public offering","source":"https://www.anthropic.com/news/anthropic-prices-initial-public-offering","published_date":"Date not detected","type":"Business","what_its_about":"AI 기업 Anthropic이 Class A 보통주 공모가를 주당 83.00달러로 확정하고 나스닥 상장을 추진한다.","key_points":["총 980,000,000주의 Class A 보통주가 공모되며, 이 중 956,351,354주는 Anthropic이, 23,648,646주는 기존 주주가 매각함","2026년 11월 19일부터 나스닥 글로벌 셀렉트 마켓에서 종목 코드 \'ANT\'로 거래가 시작될 예정임","주관사단에는 최대 147,000,000주의 추가 주식을 매입할 수 있는 30일간의 옵션이 부여됨"],"notable_data_or_quotes":["공모가: 주당 $83.00","공모 주식 수: Class A 보통주 총 980,000,000주 (Anthropic 발행 956,351,354주, 기존 주주 매각 23,648,646주)","나스닥 상장일: November 19, 2026","티커 심볼: ANT","공모 마감 예정일: November 20, 2026","초과배정옵션: 최대 147,000,000주 (30일간)"],"intended_audience":"투자자, 금융 분석가, AI 업계 관계자 및 시장 참여자","content_notes":null},{"title":"Anthropic launches roadshow for proposed initial public offering","source":"https://www.anthropic.com/news/roadshow-launch","published_date":"Date not detected","type":"Business","what_its_about":"AI 기업 Anthropic이 나스닥 상장을 목표로 클래스 A 보통주에 대한 기업공개(IPO) 로드쇼를 시작했습니다.","key_points":["Anthropic이 클래스 A 보통주 825,000,000주 규모의 기업공개(IPO)를 위한 로드쇼를 공식 개시했습니다.","예상 공모가 범위는 주당 $70.00~$78.00이며, 나스닥 글로벌 셀렉트 마켓에 \'ANT\'라는 티커 심볼로 상장 신청을 완료했습니다.","전체 공모 물량 중 801,351,354주는 회사 발행분이며 23,648,646주는 기존 주주 매각분으로 기존 주주 매각에 따른 수익금은 회사에 귀속되지 않습니다."],"notable_data_or_quotes":["총 공모 주식 수: Class A common stock 825,000,000주","회사 공모 주식 수: 801,351,354주 / 기존 주주 매각분: 23,648,646주","초과배정옵션(그린슈): 30일간 최대 123,750,000주","예상 공모가 밴드: 주당 $70.00 ~ $78.00","나스닥 티커 심볼: ANT"],"intended_audience":"투자자, 금융 및 AI 업계 관계자","content_notes":null},{"title":"AI for Science expands to foundations and research institutions","source":"https://www.anthropic.com/news/ai-for-science-expands-foundations-research-institutions","published_date":"Date not detected","type":"Research","what_its_about":"앤트로픽이 전 세계 20개 과학 재단 및 연구 기관과 파트너십을 맺고 과학자들에게 무료 클로드 크레딧을 제공하는 \'AI for Science\' 프로그램을 확대합니다.","key_points":["앤트로픽은 2025년 5월 시작된 \'AI for Science\' 프로그램을 확장하여 전 세계 20개 과학 재단 및 연구 기관에 클로드 크레딧을 지원합니다.","연구진은 가설 수립, 실험 설계, 복잡한 데이터 분석 등에 클로드를 활용하고 있으며, HHMI Janelia와 실험 기기 제어를 위한 Model Hardware Standard(MHS)를 개발하는 등 협업을 진행 중입니다.","지원 대상 파트너십을 통해 오픈 데이터셋, 오픈소스 소프트웨어, 공개 표준 등 과학 커뮤니티 전반에 기여할 공공재를 생산하고 연구 속도를 가속화할 계획입니다."],"notable_data_or_quotes":["전 세계 20개 과학 재단, 기관 및 연구 그룹","May 2025","Model Hardware Standard (MHS)","turning months of manual analysis into hours"],"intended_audience":"AI를 연구에 활용하고자 하는 과학자, 연구 기관 관계자 및 과학 기술 정책 입안자","content_notes":null},{"title":"Le Chonk brings the brains. Studio puts it to work.","source":"https://mistral.ai/news/build-with-studio/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"미스트랄 AI가 강력한 추론 능력을 갖춘 Mistral Large 4(Le Chonk) 모델과 이를 활용해 엔터프라이즈 환경에서 에이전트, 워크플로, 앱을 구축 및 배포할 수 있는 미스트랄 스튜디오(Mistral Studio)의 확장 기능을 발표했습니다.","key_points":["Mistral Large 4(Le Chonk)는 코딩, 방어적 사이버 보안, 복잡한 문서 추론 능력이 대폭 향상된 최신 오픈 모델입니다.","미스트랄 스튜디오는 클라우드, 자체 VPC, 온프레미스 등 다양한 환경에 유연하게 AI 솔루션을 배포하고 관리할 수 있는 엔터프라이즈 플랫폼입니다.","새로운 Mistral MCP 서버, 관리형 에이전트, 샌드박스, 하위 에이전트 위임 기능 등을 지원하여 비즈니스 업무 자동화 솔루션 개발을 가속화합니다."],"notable_data_or_quotes":["Mistral Large 4 (Le Chonk)","ABANCA, Accenture, Alten, BNP Paribas, Capgemini, CMA CGM, Tata Consultancy Services"],"intended_audience":"엔터프라이즈 AI 개발자, 솔루션 아키텍트, 기업 IT 및 AI 혁신 총괄자","content_notes":null},{"title":"Le Chonk: Built for Coders, Trusted by Defenders.","source":"https://mistral.ai/news/mistral-large-4-oss/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"미스트랄 AI가 코딩과 방어적 사이버보안 성능 및 추론 효율성을 대폭 개선한 1조 개 파라미터 규모의 오픈 가중치 멀티모달 모델 \'미스트랄 라지 4(Le Chonk)\'의 가중치를 정식 공개했다.","key_points":["추가 강화학습을 통해 코딩과 방어적 사이버보안 성능이 크게 향상되었으며, 오픈 가중치 모델 중 최고 수준의 코딩 벤치마크 결과를 달성했다.","추론 효율성을 개선하여 경쟁 모델 대비 훨씬 적은 토큰 소모량으로 프론티어급 코딩 성능을 제공하며, 3가지 추론 모드를 지원해 비용과 성능 간 균형을 제어할 수 있다.","유럽 인프라에서 처음부터 학습된 오픈 가중치 모델로서 기업과 기관이 자체 호스팅 및 맞춤 설정을 통해 소버린 AI를 구축할 수 있도록 지원한다."],"notable_data_or_quotes":["1-trillion-parameter","Cognition의 FrontierCode 2.0 벤치마크 점수 19.7%로 1위 기록","Artificial Analysis Coding Agent Index 48% 달성 (GLM-5.3과 동률) 및 작업당 평균 47% 적은 토큰 사용","Terminal-Bench 4.0에서 퍼블릭 프리뷰 대비 13%p 향상된 41% 기록 및 출력 토큰 30% 절감"],"intended_audience":"AI 개발자, 소프트웨어 엔지니어, 사이버보안 전문가 및 자체 인프라에서 AI 모델을 호스팅하려는 기업/기관","content_notes":null},{"title":"Mistral Advances AI for Engineering with NVIDIA","source":"https://mistral.ai/news/mistral-nvidia-ai-for-industrial-engineering/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"미스트랄(Mistral)과 엔비디아(NVIDIA)가 협력하여 AI 모델과 가속 컴퓨팅을 결합한 차세대 산업 엔지니어링 및 시뮬레이션 워크플로를 개발한다.","key_points":["Mistral Large 4 모델과 물리 모델링 파이프라인을 NVIDIA CUDA-X 및 Warp와 결합하여 시뮬레이션 속도를 높이고 폐루프 AI 설계 워크플로를 구현함","NVIDIA Omniverse 라이브러리와 연동해 GPU 가속 기반의 3D 씬 생성 및 SimReady 에셋 제작을 지원함","CAE 및 EDA 분야의 물리 모델과 에이전틱 AI 평가를 표준화하기 위한 공개 벤치마크 및 오픈 데이터셋을 구축함"],"notable_data_or_quotes":["Mistral Large 4","\\"For too long, the pace of engineering has been set by the pace of simulation. With Mistral\'s open-weight models and physics AI capabilities, combined with NVIDIA’s accelerated computing stack, we’re giving engineers faster simulation cycles, as well as open benchmarks rigorous enough to validate agents on real CAE and EDA work.\\" - Neil Ashton, VP of Computational Engineering, Mistral","“The next wave of engineering breakthroughs will come from exploring ideas that were once too complex or time-consuming to test,” - Tim Costa, vice president and general manager of industrial and computational engineering at NVIDIA"],"intended_audience":"항공우주, 자동차, 반도체 분야의 엔지니어링 연구원, CAE/EDA 개발자 및 산업용 AI 솔루션 도입 실무자","content_notes":null},{"title":"Voxtral 3","source":"https://mistral.ai/news/voxtral-3/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Mistral AI가 실시간 다단계 음성 대화와 도구 연동을 지원하는 차세대 음성 에이전트 SDK 및 음성 모델 제품군인 Voxtral 3을 발표했습니다.","key_points":["50개 이상의 언어를 지원하며 정확한 음성 전사, 화자 분리, 문맥 편향 및 발화 종료 감지 기능을 제공합니다.","듣기, 사고 및 추론, 도구 호출, 감정 표현이 가능한 음성 합성을 단일 실시간 스트리밍 파이프라인으로 통합했습니다.","EU 호스팅 API 및 자체 인프라 배포를 지원하여 데이터 주권과 보안 통제권을 보장합니다."],"notable_data_or_quotes":["Voxtral 3","50+ languages","Voxtral Small Transcribe 3","Mistral’s EU-hosted API"],"intended_audience":"음성 기반 AI 에이전트 및 고객 상담 솔루션을 구축하려는 개발자, 데이터 주권과 온프레미스 배포가 필요한 엔터프라이즈 기업","content_notes":null},{"title":"Introducing Timestral","source":"https://mistral.ai/news/timestral/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Mistral이 최대 209M 파라미터 규모로 주요 벤치마크 1위를 달성한 다변량 시계열 파운데이션 모델 패밀리 \'Timestral\'을 공개했습니다.","key_points":["Mistral이 5M부터 209M 파라미터까지 총 4가지 크기로 구성된 시계열 파운데이션 모델 패밀리 Timestral을 발표했습니다.","합성 사전학습, 공변량 인식 어텐션, 롱 컨텍스트 학습을 결합하여 CPU에서도 효율적으로 실행되며 제로샷 다변량\xb7확률론적 예측을 지원합니다.","최대 모델(209M)은 기존 SOTA 대비 3분의 2 수준의 파라미터만으로 GIFT-Eval, TIME, fev-bench 등 3대 공개 벤치마크에서 1위를 기록했습니다."],"notable_data_or_quotes":["209M parameters","GIFT-Eval, TIME, and fev-bench","four sizes (5M to 209M parameters)","5M, 28M, 123M and 209M parameters","outperforming the previous state of the art with only two-thirds of the model parameters"],"intended_audience":"시계열 데이터 예측 및 파운데이션 모델을 활용하려는 머신러닝 엔지니어, 데이터 사이언티스트, 엔터프라이즈 분석 담당자","content_notes":null},{"title":"Can Anthropic afford to put safety first?","source":"https://www.theverge.com/podcast/1038701/anthropic-ipo-ai-safety-openai-nvidia-structure","published_date":"2026-11-21","type":"Business","what_its_about":"나스닥 상장을 진행한 앤트로픽(Anthropic)이 주주들의 이익 추구 압박과 막대한 연산 비용 속에서 기존의 AI 안전성 중심 기조를 유지할 수 있을지 다룬 팟캐스트 인터뷰 기사입니다.","key_points":["클로드 개발사인 앤트로픽이 순수 AI 연구 기업 중 최초로 나스닥에 상장하며 세계 최고 가치 기업 중 하나로 부상했습니다.","향후 수년간 약 9,000억 달러에 달하는 막대한 컴퓨팅 비용과 주주 가치 극대화 압박 속에서, 핵심 차별점이었던 AI 안전성 가치와의 긴장 관계가 시험대에 올랐습니다.","자본주의 시장 압박에 대응하기 위한 독특한 기업 지배구조와 창업자들의 통제력, 그리고 OpenAI가 먼저 상장하도록 지켜본 배경 등을 심층적으로 논의합니다."],"notable_data_or_quotes":["roughly $900 billion over the coming years","They priced the IPO at $83 a share and they got all the way up to $111."],"intended_audience":"AI 기업 투자자, 테크 산업 분석가, AI 안전성 및 기업 지배구조에 관심 있는 기술 업계 종사자","content_notes":null},{"title":"Meet Thinking Machines Inkling 2 Mini: 26B Looped MoE Runs on a 32GB Mac","source":"https://www.marktechpost.com/2026/11/21/thinking-machines-inkling-2-mini-looped-transformer/","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"Thinking Machines Lab이 중간 레이어를 반복 재사용하는 루프형 MoE 구조를 통해 32GB Mac 등 로컬 환경에서 구동 가능한 26.4B 오픈소스 모델 Inkling 2 Mini를 공개했다.","key_points":["총 파라미터 26.4B(활성 3.4B) 규모의 희소 MoE 모델로, 중간 2개 블록을 3회 반복 실행해 체크포인트 크기를 약 20GB 수준으로 유지하면서 추론 효율을 극대화함","32GB 이상의 Apple Silicon Mac 및 단일 NVIDIA DGX Spark 등 로컬 환경에서 에이전틱 코딩, 도구 활용, 문서 작업에 적합하도록 설계되었으며 Apache 2.0 라이선스로 배포됨","SWE-bench Verified(bash 전용) 79.2% 등 코딩 및 에이전트 작업에서 강력한 성능을 보이지만, 지식 회상 및 다자간 대화 지시 수행 능력은 상대적으로 약점을 보임"],"notable_data_or_quotes":["26.4B total parameters, 3.4B active","checkpoint near 20GB","32GB Mac or 1 NVIDIA DGX Spark","SWE-bench Verified (bash only) 79.2%","Apache 2.0"],"intended_audience":"로컬 환경에서 고성능 코딩 및 에이전트 워크플로우를 구축하려는 AI 개발자 및 엔지니어","content_notes":null},{"title":"OpenAI Ships GPT-Live-1.1 for Voice Agents, Cuts Idle Cost to $0.02/Min","source":"https://www.marktechpost.com/2026/11/21/openai-gpt-live-1-1-api-standby-mode/","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"OpenAI가 음성 에이전트를 위한 양방향 음성 모델 GPT-Live-1.1을 API로 출시하고 대기 모드를 통해 유휴 비용을 60% 절감했습니다.","key_points":["OpenAI가 말하면서 동시에 들을 수 있는 전이중(full-duplex) 다국어 음성 모델인 GPT-Live-1.1을 API에 공개했습니다.","유휴 상태의 WebRTC 세션을 기존 분당 $0.05에서 $0.02로 낮춘 \'대기(Standby) 모드\'를 도입해 음성 에이전트 운영 비용을 대폭 줄였습니다.","음성 인식, 다국어 억양, 문자 및 숫자 처리, 지시 수행 성능이 개선되었으며, 복잡한 추론이나 툴 호출은 GPT-6 Astra나 Luna 같은 백엔드 텍스트 모델로 위임할 수 있습니다."],"notable_data_or_quotes":["Standby bills idle WebRTC time at $0.02 per minute versus $0.05 active , a 60% lower rate.","Live sessions hold a 128,000-token default context window","OpenAI published 0 benchmark scores for 1.1","September 10, 2026","October 15","Instructions can run up to 16,384 tokens"],"intended_audience":"음성 AI 에이전트 및 고객 상담 솔루션을 구축하는 개발자와 기업","content_notes":null},{"title":"Baseten Releases Bison-1 and Groundhog-1, Topping Decision Model Index","source":"https://www.marktechpost.com/2026/11/20/baseten-bison-1-groundhog-1-gemma-4-decision-models/","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"Baseten이 Google의 Gemma 4를 기반으로 텍스트를 생성하지 않고 보정된 확률값을 반환하는 오픈 웨이트 의사결정 모델 bison-1과 groundhog-1을 출시했습니다.","key_points":["bison-1과 groundhog-1은 텍스트 생성이 아닌 예/아니오, 선택형, 점수형 질문에 보정된 확률값만을 단일 프리필 패스로 반환하는 결정 모델입니다.","두 모델 모두 컨텍스트 길이를 기존 16k에서 128k(131,072) 토큰으로 확장하고 이미지 입력을 지원하여 티켓 분류, 가드레일, LLM 라우팅 등에 최적화되었습니다.","31B dense 모델인 bison-1은 Artificial Analysis Decision Index v2.1에서 76점을 기록해 1위를 차지했으며 가장 우수한 보정 성능(Brier 점수 0.14)을 보여주었습니다."],"notable_data_or_quotes":["AA Decision Index v2.1: bison-1 76점 (1위), Liquid AI d1.2-ultra 75점 (2위)","Brier score: 0.14 (낮을수록 우수)","컨텍스트 윈도우: 128k 토큰 (131,072)","가격: 100만 입력 토큰당 $0.10","모델 크기 및 구조: bison-1은 31B dense, groundhog-1은 26B MoE (토큰당 활성 파라미터 약 4B)"],"intended_audience":"LLM 라우팅, 가드레일, 분류 파이프라인을 구축 및 최적화하는 AI 엔지니어 및 백엔드 개발자","content_notes":null},{"title":"추론 칩을 바이브 코딩하기","source":"https://news.hada.io/topic?id=37581&utm_source=geeknews&utm_medium=rss&utm_campaign=news","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"코딩 에이전트를 활용해 하드웨어 개발 경험 없이도 AWS FPGA 기반 LLM 추론 속도를 33배 개선한 실험 사례","key_points":["하드웨어 개발 경험이 거의 없는 상태에서 코딩 에이전트를 사용해 AWS FPGA 환경에서 LLM 추론을 구현함","메모리 접근, 병렬화, 파이프라인, 추측 디코딩 등 점진적 최적화를 거쳐 최초 구현 대비 속도를 33배 향상시킴","Conductor에서 실행된 에이전트가 며칠간 수백 차례 실험하며 대규모 코드 작성 및 분석을 수행함"],"notable_data_or_quotes":["최초 구현 대비 속도 33배 향상","누적 약 300만 줄의 코드 작성","3,000만 줄의 출력 파일 분석","토큰 비용 약 1만 달러","최종 속도 213.13토큰/초 도달","24턴 벤치마크"],"intended_audience":"AI 엔지니어, 하드웨어 가속기 및 FPGA 개발자, LLM 최적화에 관심 있는 개발자","content_notes":null},{"title":"OpenAI, 내부 연구 모델이 DNS 설정 오류로 인터넷에 접근해 최상위 모델 학습을 11일간 중단","source":"https://news.hada.io/topic?id=37575&utm_source=geeknews&utm_medium=rss&utm_campaign=news","published_date":"2026-11-21","type":"Security","what_its_about":"OpenAI의 내부 연구 모델이 DNS 설정 오류로 인해 인터넷에 제한적으로 접근하자 최상위 모델의 학습과 평가가 11일간 중단된 사건을 다룹니다.","key_points":["감시 시스템이 내부 연구 모델의 DNS 설정 오류를 통한 제한적 인터넷 접근을 탐지했습니다.","해당 이슈로 인해 9월 20일부터 10월 1일까지 11일 동안 최고 성능 모델들의 학습과 평가가 전면 중단되었습니다.","중지 지시 시 35초 내 모델 출력을 멈추는 \'Control Room\' 등 모델 학습\xb7배포 단계의 안전 시스템 구조가 함께 공개되었습니다."],"notable_data_or_quotes":["9월 20일부터 10월 1일까지","11일간 중단","Control Room: 중지 지시를 받으면 35초 안에 모델 출력을 멈추는 장치"],"intended_audience":"AI 안전 연구자, 인공지능 개발자 및 기술 보안 담당자","content_notes":null},{"title":"Show GN: Claude로 만든 디스코드 개인 비서 — 결제 문자 자동 가계부까지 (MIT, 무료 서버로 운영)","source":"https://news.hada.io/topic?id=37569&utm_source=geeknews&utm_medium=rss&utm_campaign=news","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"Claude와 디스코드를 연동하여 일정, 메일, 날씨 브리핑 및 결제 문자 기반 자동 가계부 기능을 제공하는 무료 개인 비서 봇 프로젝트 소개","key_points":["디스코드 채팅을 통해 Claude와 대화하며 질문, 검색, 메일 요약 및 아침 통합 브리핑을 받을 수 있음","!out 명령어로 실시간 버스 도착 정보를 확인해 외출 타이밍을 안내함","스마트폰의 전달 앱과 연동하여 신한\xb7KB\xb7삼성 등 카드 결제 문자를 감지하고 상호명 분류, 중복 및 취소 처리까지 지원하는 자동 지출 기록 기능 제공"],"notable_data_or_quotes":["MIT 라이선스 및 무료 서버 운영","카드 결제 문자 → 자동 지출 기록 (신한\xb7KB\xb7삼성 확인)"],"intended_audience":"Claude API를 활용해 개인 업무 자동화 및 가계부 정리를 구축하려는 개발자 및 파워 유저","content_notes":null},{"title":"Show GN: codemap-search - 코딩 에이전트용 단일 바이너리 Rust 코드 탐색 MCP 서버","source":"https://news.hada.io/topic?id=37568&utm_source=geeknews&utm_medium=rss&utm_campaign=news","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"코딩 에이전트의 효율적인 로컬 저장소 탐색을 지원하는 Rust 기반의 경량 단일 바이너리 MCP 서버인 codemap-search를 소개합니다.","key_points":["별도의 런타임이나 데이터베이스 없이 Tree-sitter, Tantivy BM25, 호출 관계 추적 및 기본 탐색 도구를 단일 바이너리로 결합하여 색인 부담과 탐색 비효율 문제를 해결했습니다.","기존 오픈소스 MCP 도구 및 rg 기준군과의 비교 벤치마크에서 세 가지 환경 모두 최고 수준의 검색 정확도(96~98/108)를 기록했습니다.","Grafana 기준 약 2.4만 개 파일의 색인을 13~16초 만에 완료하며 디스크 사용량은 약 137MB에 불과해 빠른 처리 속도와 가벼운 리소스 사용량을 보입니다."],"notable_data_or_quotes":["Grafana(약 2.4만 파일)","정확도에서는 codemap-search가 세 환경 모두 가장 높았고(96~98/108 vs rg 86~89/108)","Grafana 색인은 13~16초, 디스크 약 137MB 수준"],"intended_audience":"Claude Code나 Codex 등 코딩 에이전트를 활용하며 로컬 코드베이스 탐색 효율을 높이고자 하는 개발자","content_notes":null},{"title":"Slopstrap - 사이트를 급하게 바이브 코딩한 것처럼 보이게 만들기","source":"https://news.hada.io/topic?id=37563&utm_source=geeknews&utm_medium=rss&utm_campaign=news","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"웹사이트를 LLM이 급하게 만든 듯한 전형적인 AI 스타일로 꾸밀 수 있는 CSS 프레임워크 Slopstrap을 소개합니다.","key_points":["빌드 도구 없이 CSS와 JavaScript를 추가하여 복사해 붙여넣는 방식으로 손쉽게 사용할 수 있습니다.","다크 모드, 빛나는 구체 배경, 그라데이션 글자, 벤토 그리드 등 전형적인 LLM 풍의 시각 요소를 제공합니다.","가짜 추천사, 스타트업 로고 띠, 숫자 카운터 등의 콘텐츠 요소를 갖추고 있으며 Slopstrap.slopify() 한 줄로 기존 컨테이너를 변환할 수 있습니다."],"notable_data_or_quotes":["Slopstrap.slopify()"],"intended_audience":"웹 개발자, 디자이너 및 AI 패러디 도구에 관심 있는 IT 종사자","content_notes":null},{"title":"“Race realism” isn’t realistic—and it isn’t good science","source":"https://arstechnica.com/science/2026/11/race-realism-isnt-realistic-and-it-isnt-good-science/","published_date":"2026-11-21","type":"Research","what_its_about":"정치권과 온라인 등에서 다시 고개를 들고 있는 \'인종 현실주의\' 또는 \'인종 과학\' 주장이 과학적 근거가 없음을 지적하고 비판하는 기사입니다.","key_points":["서구 정치권에서 특정 인종 집단의 지능이 선천적으로 열등하다는 식의 \'인종 과학\' 및 \'인종 현실주의\' 담론이 재부상하고 있습니다.","이러한 인종주의적 주장은 극우 선전과 소셜 미디어 허위 정보 확산에 활용되고 있으나, 실제로는 과학적 타당성을 갖추지 못하고 있습니다.","네이선 코프너스(Nathan Cofnas) 등 일부 인사가 고(故) 제이슨 아데이(Jason Arday) 교수를 표절 혐의로 고발하는 등 관련 논란이 사회적 주목을 받고 있습니다."],"notable_data_or_quotes":["\\"I always say these are low-IQ people\\"","2024"],"intended_audience":"인류학 및 유전학 등 과학계 연구자, 사회과학 및 인종 담론에 관심 있는 일반 독자 및 정책 관계자","content_notes":"내용 불완전"},{"title":"Attackers\' AI Agents Found a Zero-Day in Medical-Imaging Software and Gained Root Access","source":"https://thehackernews.com/2026/11/attackers-ai-agents-found-zero-day-in.html","published_date":"2026-11-21","type":"Security","what_its_about":"중국 연계 해커가 자율형 AI 에이전트를 활용해 의료 영상 소프트웨어 MONAI Label의 제로데이 취약점을 발견하고 대학 서버의 루트 권한을 탈취했습니다.","key_points":["중국 연계 해커들이 자동화 침투 테스트 프레임워크인 Cairn 기반 AI 에이전트를 이용해 MONAI Label 0.8.5 및 이전 버전의 경로 순회(path-traversal) 제로데이 취약점을 발견했습니다.","기본 설정상 인증이 비활성화된 취약점을 악용하여, AI 에이전트는 별도의 단계별 지시 없이 스스로 방식을 선택해 약 11분 만에 서버 내 파일 쓰기에 성공했습니다.","에이전트는 Python 시작 시 자동 실행되는 파일을 심고 학습 기능을 작동시켜 최종적으로 대학 서버의 루트(root) 셸 권한을 획득했습니다."],"notable_data_or_quotes":["MONAI Label 0.8.5 및 이전 버전 영향","약 48시간 동안 인터페이스 매핑 후 대략 11분 만에 서버 파일 쓰기 도달","오픈소스 침투 테스트 프레임워크 Cairn 활용","Amazon Threat Intelligence 조사 발표"],"intended_audience":"보안 연구원, 시스템 관리자, AI 및 의료 소프트웨어 개발자","content_notes":null},{"title":"Signal Blocks AI Agents From Reading Private Chats via Screenshots on Android and iOS","source":"https://thehackernews.com/2026/11/signal-blocks-ai-agents-from-reading.html","published_date":"2026-11-21","type":"Security","what_its_about":"시그널이 모바일 운영체제의 AI 에이전트가 화면 스크린샷을 통해 개인 대화 내용을 무단 스캔하는 것을 막기 위해 기본 스크린샷 제한 조치를 도입했습니다.","key_points":["시그널은 안드로이드와 iOS 기기에서 OS 내장 AI 에이전트의 화면 감시를 차단하기 위해 화면 캡처 방지 기능을 기본 활성화했습니다.","시그널 재단 대표 메러디스 휘태커는 OS 수준의 AI 에이전트 기능이 시그널의 독자적인 프라이버시 보장을 훼손하는 \'존재론적 위협\'이라고 경고했습니다.","스크린샷 차단만으로는 파일 시스템 직접 접근 등 다른 우회 경로를 완전히 막을 수 없으므로, 시그널은 빅테크 기업에 명확한 AI 접근 제외(opt-out) 수단과 투명한 기술 문서 제공을 요구했습니다."],"notable_data_or_quotes":["Meredith Whittaker: \\"In order to gain access to information about you, these OS AI agents \'scan\' the information that\'s on your screen\\"","Meredith Whittaker는 OS AI 기능 통합을 시그널에 대한 \\"existential threat to Signal\\"(존재론적 위협)로 규정함","Signal: \\"Our remedy is also incomplete\\"","적용 경로: Settings > Privacy > App Security > \'Block Siri AI\'(iOS) 또는 \'Screen security\'(Android)"],"intended_audience":"개인정보 보호 및 메시징 보안에 관심이 있는 모바일 사용자, 앱 개발자, 보안 실무자","content_notes":null},{"title":"AI 작업 능력, 6개월 만에 16시간→40시간…\\"판단력 여전히 한계\\"","source":"https://www.aitimes.com/news/articleView.html?idxno=217649","published_date":"2026-11-21","type":"Research","what_its_about":"AI 안전성 평가기관 METR의 평가 결과, 최첨단 AI 모델들의 작업 수행 능력이 인간 전문가 기준 40시간 수준까지 빠르게 발전했으나 연구 판단력에는 여전히 한계가 있는 것으로 나타났다.","key_points":["METR의 \'시간 지평\' 평가에서 GPT-6 아스트라가 약 40시간, 클로드 오퍼스 5.5가 약 39시간을 기록하며 6개월 만에 16시간에서 크게 증가함","프로그래밍 최적화 대회 참가자의 96~98%를 앞서는 등 코딩과 알고리즘 최적화에서는 대부분의 인간 전문가를 뛰어넘는 성과를 보임","결과를 즉시 검증할 수 있는 작업에는 강하나 가설 선택이나 연구 가치 평가 등 자율적인 연구 판단 능력에는 여전히 한계가 존재함"],"notable_data_or_quotes":["GPT-6 아스트라 약 40시간, 클로드 오퍼스 5.5 약 39시간의 시간 지평 기록","시간 지평이 두 배로 늘어나는 기간은 평균 3.61개월(약 110일)","프로그래밍 최적화 대회 15개 기록 비교 결과 최상위 AI 모델이 인간 참가자의 96~98%보다 높은 점수 기록","사야시 카푸어: \'연구자가 유망한 질문과 가설, 실험을 선택하는 능력이 AI 연구개발 자동화의 주요 장애물이 될 것\'"],"intended_audience":"AI 연구원, 소프트웨어 엔지니어 및 AI 기술 발전 동향에 관심 있는 테크 업계 종사자","content_notes":null},{"title":"구글, 제미나이 앱에 GIF 생성 기능 출시…오픈AI 이어 도입","source":"https://www.aitimes.com/news/articleView.html?idxno=217648","published_date":"2026-11-21","type":"Consumer","what_its_about":"구글이 제미나이 앱에 텍스트 프롬프트를 통해 약 3초 길이의 GIF 이미지를 제작할 수 있는 신규 기능을 출시했다.","key_points":["구글의 영상 생성 모델 \'제미나이 옴니 1.2 플래시\'를 기반으로 텍스트 입력을 통해 약 3초 길이의 반복 애니메이션 GIF를 생성","한국, 미국 등 8개국에서 순차 제공되며 유료 구독자뿐만 아니라 무료 이용자도 사용 가능","오픈AI가 챗GPT에 GIF 생성 기능을 선보인 지 약 2주(16일) 만에 도입되어 빅테크 간 애니메이션 생성 경쟁 가속화"],"notable_data_or_quotes":["20일(현지시간)","약 3초 길이","미국, 캐나다, 영국, 일본, 한국, 호주, 독일, 프랑스 등 8개국","오픈AI는 앞서 지난 4일 이미지 생성 모델 \'이미지 2.6\'을 출시","16일 만에"],"intended_audience":"생성형 AI 서비스 사용자 및 SNS\xb7메신저용 밈/움짤 제작에 관심 있는 일반 소비자","content_notes":null},{"title":"[11월20일] 구글 \\"AGI는 끝이 아니다\\"…AGI 이후 4가지 발전 경로 제시","source":"https://www.aitimes.com/news/articleView.html?idxno=217605","published_date":"2026-11-21","type":"Research","what_its_about":"구글 딥마인드가 인간 수준의 AGI 도달 이후 초지능(ASI)으로 나아가는 네 가지 핵심 기술 발전 경로와 과제를 제시했습니다.","key_points":["AGI 이후 발전 경로로 스케일링 법칙 지속, LLM 한계 극복(지속 학습 및 월드 모델), 에이전트 결합 기반의 집단지능 및 인지적 산업화, 재귀적 자기개선(RSI)의 4가지를 제시함","비용 절감과 효율 개선을 통해 수많은 AI 에이전트가 협업하는 집단지능을 구축하여 대규모 인간 전문가 집단을 능가할 수 있음","AI가 차세대 AI를 개발하는 재귀적 자기개선이 가능해질 수 있으나 안전성 검증 및 기술적 돌파구 마련 등의 과제가 존재함"],"notable_data_or_quotes":["2030년 무렵 AGI에 도달할 것이라는 전망","19일(현지시간) \'What comes after AGI?\'","셰인 레그 등 연구진 14명이 지난 6월 발표한 기술 보고서 \'From AGI to ASI\'","10년 뒤에는 오늘날 AI 에이전트 하나를 실행하는 자원으로 세계 인구보다 많은 에이전트를 가동할 수도 있다"],"intended_audience":"AI 연구자, 기술 정책 입안자, 인공지능 미래 전망에 관심 있는 IT 종사자","content_notes":null},{"title":"아이디어가 게임이 되기까지 24시간…\'유니티 AI 게임잼\' 현장 가보니","source":"https://zdnet.co.kr/view/?no=20261120190933","published_date":"2026-11-21","type":"Tools/Dev","what_its_about":"유니티와 한국게임산업협회가 부산 벡스코에서 AI 도구를 활용해 24시간 만에 게임을 제작하는 \'유니티 AI 게임잼\'을 성공적으로 개최했다.","key_points":["유니티가 글로벌 최초로 시도한 오프라인 AI 게임잼으로, 54명의 참가자가 AI 도구를 활용해 기존 2박 3일 일정을 24시간으로 단축하여 게임을 완성했다.","오픈AI와 메쉬AI가 공식 스폰서로 참여했으며, 참가자들은 유니티 CLI와 코덱스(Codex) 플러그인 등 다양한 AI 기술을 접목해 개발을 진행했다.","20대부터 50대까지 다양한 연령과 경력의 개발자 4명으로 구성된 팀이 최종 우승을 차지했고, 우수작 3종은 지스타 2026 \'유니티 월드\'에 전시됐다."],"notable_data_or_quotes":["지난 18일부터 19일까지 부산 벡스코에서 \'유니티 AI 게임잼\'을 개최했다.","서류 심사를 거쳐 선발된 참가자 54명이 무박 24시간 동안 AI를 활용해 게임을 제작했다.","김범주 유니티 APAC 애드보커시 리더: \'올해는 AI가 중요한 화두로 떠올랐고 유니티에서도 관련 기술을 개발하고 있어 AI를 적극 활용하는 게임잼을 기획했다\'","지스타 2026 벡스코 제2전시장 1층 B2C관에 마련된 \'유니티 월드\'에 전시됐다."],"intended_audience":"게임 개발자, AI 기반 소프트웨어 개발자, 인디 게임 제작자 및 게임 산업 종사자","content_notes":null}],"skipped":[],"disclaimer":"이 요약은 보고서 파일에 수집된 본문만을 기반으로 작성되었습니다. 외부 사이트 접속 및 AI 생성 내용은 포함되지 않았습니다."}')}}]);